import{_ as a,c as t,o,ag as i}from"./chunks/framework.DWdSXOaE.js";const g=JSON.parse('{"title":"Layouts","description":"","frontmatter":{},"headers":[],"relativePath":"design-standards/layouts.md","filePath":"design-standards/layouts.md"}'),r={name:"design-standards/layouts.md"};function n(s,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h1><p>The spatial arrangement of elements is key to the Fluxive Blueprint Theme. We utilize a grid-based background and specific container widths to create a sense of structure.</p><h2 id="the-grid-background" tabindex="-1">The Grid Background <a class="header-anchor" href="#the-grid-background" aria-label="Permalink to &quot;The Grid Background&quot;">​</a></h2><p>To give the application a &quot;technical&quot; feel, the main background canvas is not just a solid color. It is a subtle grid pattern on top of the deep gray background.</p><ul><li><strong>Base Color</strong>: <code>#111827</code> (Gray 900)</li><li><strong>Pattern</strong>: 1px lines of <code>rgba(255, 255, 255, 0.03)</code></li><li><strong>Grid Size</strong>: <code>32px</code> x <code>32px</code></li></ul><p>This subtle texture prevents the large dark areas from feeling &quot;dead&quot; or empty.</p><h2 id="page-structure" tabindex="-1">Page Structure <a class="header-anchor" href="#page-structure" aria-label="Permalink to &quot;Page Structure&quot;">​</a></h2><h3 id="container" tabindex="-1">Container <a class="header-anchor" href="#container" aria-label="Permalink to &quot;Container&quot;">​</a></h3><p>Pages typically use a centered container layout for readability.</p><ul><li><strong>Max Width</strong>: <code>1280px</code> (standard desktop) or <code>1440px</code> (dashboard view)</li><li><strong>Padding</strong>: <code>24px</code> horizontal padding on mobile, <code>32px</code> on desktop.</li></ul><h3 id="sidebar-layout" tabindex="-1">Sidebar Layout <a class="header-anchor" href="#sidebar-layout" aria-label="Permalink to &quot;Sidebar Layout&quot;">​</a></h3><p>For documentation and complex apps (like Studio), we use a persistent sidebar.</p><ul><li><strong>Width</strong>: <code>280px</code> or <code>320px</code></li><li><strong>Position</strong>: Fixed left</li><li><strong>Styling</strong>: Uses the <a href="./components.html#glassmorphism">Glassmorphism</a> style to sit &quot;above&quot; the main content.</li></ul><h2 id="spacing-system" tabindex="-1">Spacing System <a class="header-anchor" href="#spacing-system" aria-label="Permalink to &quot;Spacing System&quot;">​</a></h2><p>We adhere to a 4px baseline grid (Tailwind spacing scale). Common spacing values:</p><ul><li><code>4px</code> (0.25rem) - Tight spacing within components</li><li><code>8px</code> (0.5rem) - Standard icon/text gap</li><li><code>16px</code> (1rem) - Content padding, standard gap between elements</li><li><code>24px</code> (1.5rem) - Card padding</li><li><code>32px</code> (2rem) - Section separation</li><li><code>64px</code> (4rem) - Major page sections</li></ul>',16)])])}const h=a(r,[["render",n]]);export{g as __pageData,h as default};
